function countRichSubarrays(nums: number[], k: number): number {
  const n = nums.length;
  let total = 0;
  for (let i = 0; i < n; i++) {
    const count = new Map<number, number>();
    let pairs = 0;
    for (let j = i; j < n; j++) {
      const c = count.get(nums[j]) ?? 0;
      pairs += c;
      count.set(nums[j], c + 1);
      if (pairs >= k) { total += n - j; break; }
    }
  }
  return total;
}

