function countRichSubarrays(nums: number[], k: number): number {
  const count = new Map<number, number>();
  let pairs = 0, left = 0, total = 0;
  for (const x of nums) {
    const c = count.get(x) ?? 0;
    pairs += c;
    count.set(x, c + 1);
    while (pairs >= k) {
      const y = nums[left++];
      const d = count.get(y)! - 1;
      count.set(y, d);
      pairs -= d;
    }
    total += left;
  }
  return total;
}

